import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    if k < 1:
        return 1
    terms = range(k, k + n)
    if not terms:
        return 1
    return reduce(lcm, terms)

# Test n=7 for k=1 to 20
n_test = 7
k_values = range(1, 21)
results = {}
for k in k_values:
    x_k = calculate_x_k(k, n_test)
    results[k] = x_k

# Check ratios x_{k+1} / x_k
ratios = {}
for k in range(1, 20):
    x_k = results[k]
    x_k_plus_1 = results[k+1]
    ratio = x_k_plus_1 / x_k
    ratios[k] = ratio

print("--- n=7 Sequence Terms (k=1 to 20) ---")
for k, x_k in results.items():
    print(f"k={k}: x_k = {x_k}")

print("\n--- Ratios x_{k+1} / x_k (k=1 to 19) ---")
for k, ratio in ratios.items():
    print(f"Ratio at k={k}: {ratio:.4f}")
